package com.ykis.ykismobkmp.ui.screens.meterimport androidx.compose.animation.AnimatedVisibilityimport androidx.compose.animation.core.tweenimport androidx.compose.animation.fadeInimport androidx.compose.animation.fadeOutimport androidx.compose.foundation.backgroundimport androidx.compose.foundation.layout.*import androidx.compose.material3.*import androidx.compose.runtime.*import androidx.compose.ui.Alignmentimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpimport cafe.adriel.voyager.core.annotation.InternalVoyagerApiimport cafe.adriel.voyager.core.screen.Screenimport cafe.adriel.voyager.navigator.internal.BackHandlerimport com.ykis.ykismobkmp.domain.entity.HeatMeterEntityimport com.ykis.ykismobkmp.domain.entity.WaterMeterEntityimport com.ykis.ykismobkmp.ui.BaseUIStateimport com.ykis.ykismobkmp.ui.navigation.ContentDetailimport com.ykis.ykismobkmp.ui.navigation.ContentTypeimport com.ykis.ykismobkmp.ui.navigation.LocalContentTypeimport com.ykis.ykismobkmp.ui.screens.appartment.ApartmentScreenModelimport org.koin.compose.koinInjectprivate const val className = "MainMeterScreen"class MainMeterScreen(  private val onDrawerClick: () -> Unit = {}) : Screen {  @Composable  override fun Content() {    val adaptiveContentType = LocalContentType.current    val meterScreenModel = koinInject<MeterScreenModel>()    val apartmentScreenModel = koinInject<ApartmentScreenModel>()    val baseUIState by apartmentScreenModel.uiState.collectAsState()    MainMeterScreenInternal(      modifier = Modifier.fillMaxSize(),      viewModel = meterScreenModel,      baseUIState = baseUIState,      onDrawerClick = onDrawerClick,      contentType = adaptiveContentType    )  }}@Composable fun MainMeterScreenInternal(  modifier: Modifier = Modifier,  viewModel: MeterScreenModel,  baseUIState: BaseUIState,  onDrawerClick: () -> Unit,  contentType: ContentType) {  val methodName = "MainMeterScreenInternal"  LaunchedEffect(baseUIState.addressId) {    val uid = baseUIState.uid ?: ""    val addressId = baseUIState.addressId    if (uid.isNotEmpty() && addressId > 0L) {      println("[YkisLogKMP.$className.$methodName.LaunchedEffect]: Завантаження лічильників ЮКІС для о/р Long: $addressId")      viewModel.getWaterMeterList(uid, addressId)      viewModel.getHeatMeterList(uid, addressId)    }  }  val meterUIState by viewModel.uiState.collectAsState()  val selectedTab = meterUIState.selectedTab  val showDetail = meterUIState.showDetail  val contentDetail = meterUIState.selectedContentDetail  if (contentType == ContentType.DUAL_PANE) {    Row(modifier = modifier.fillMaxSize()) {      Box(modifier = Modifier.weight(0.4f)) {        MeterListScreen(          baseUIState = baseUIState,          onDrawerClick = onDrawerClick,          viewModel = viewModel,          onWaterMeterClick = { viewModel.setWaterMeterDetail(it) },          onHeatMeterClick = { viewModel.setHeatMeterDetail(it) },          meterUIState = meterUIState,          selectedTab = selectedTab,          onTabClick = { viewModel.onTabSelect(it) }        )      }      VerticalDivider(thickness = 1.dp, color = MaterialTheme.colorScheme.outlineVariant)      Box(modifier = Modifier.weight(0.6f)) {        if (showDetail) {          MeterDetailScreen(            modifier = Modifier.background(MaterialTheme.colorScheme.surface),            contentDetail = contentDetail,            meterUIState = meterUIState,            viewModel = viewModel,            baseUIState = baseUIState          )        } else {          // ИСПРАВЛЕНО НАМЕРТВО: Текст плейсхолдера полностью переведен под бренд ЮКІС!          EmptyDetailPlaceholder("Виберіть лічильник для перегляду деталей споживання ЮКІС")        }      }    }  } else {    SinglePanelMeter(      contentDetail = contentDetail,      baseUIState = baseUIState,      onDrawerClick = onDrawerClick,      showDetail = showDetail,      viewModel = viewModel,      meterUIState = meterUIState,      selectedTab = selectedTab,      onWaterMeterClick = { viewModel.setWaterMeterDetail(it) },      onHeatMeterClick = { viewModel.setHeatMeterDetail(it) }    )  }}@Composableprivate fun SinglePanelMeter(  modifier: Modifier = Modifier,  contentDetail: ContentDetail,  baseUIState: BaseUIState,  onDrawerClick: () -> Unit,  showDetail: Boolean,  viewModel: MeterScreenModel,  meterUIState: BaseUIState,  selectedTab: Int,  onWaterMeterClick: (WaterMeterEntity) -> Unit,  onHeatMeterClick: (HeatMeterEntity) -> Unit,) {  Box(modifier = modifier.fillMaxSize()) {    if (!showDetail) {      MeterListScreen(        baseUIState = baseUIState,        onDrawerClick = onDrawerClick,        viewModel = viewModel,        onHeatMeterClick = onHeatMeterClick,        onWaterMeterClick = onWaterMeterClick,        meterUIState = meterUIState,        selectedTab = selectedTab,        onTabClick = { viewModel.onTabSelect(it) }      )    }    AnimatedVisibility(      visible = showDetail,      enter = fadeIn(tween(300)),      exit = fadeOut(tween(300))    ) {      MeterDetailBackHandler(contentDetail, viewModel)      MeterDetailScreen(        modifier = Modifier.background(MaterialTheme.colorScheme.background).fillMaxSize(),        contentDetail = contentDetail,        meterUIState = meterUIState,        viewModel = viewModel,        baseUIState = baseUIState      )    }  }}@OptIn(InternalVoyagerApi::class)@Composableprivate fun MeterDetailBackHandler(contentDetail: ContentDetail, viewModel: MeterScreenModel) {  val methodName = "BackHandler"  BackHandler(enabled = true) {    println("[YkisLogKMP.$className.$methodName]: Системне перехоплення кнопки Назад. Скидання контексту споживання ЮКІС.")    when (contentDetail) {      ContentDetail.WATER_READINGS -> viewModel.setContentDetail(ContentDetail.WATER_METER)      ContentDetail.HEAT_READINGS -> viewModel.setContentDetail(ContentDetail.HEAT_METER)      else -> viewModel.closeContentDetail()    }  }}@Composablefun EmptyDetailPlaceholder(text: String) {  Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {    Text(text, style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)  }}